// Builds supabase/seed.sql from supabase/seed-data/catalog.json.
// Run: npm run seed
import { readFileSync, writeFileSync } from "node:fs";

const data = JSON.parse(readFileSync(new URL("../supabase/seed-data/catalog.json", import.meta.url), "utf8"));
const q = (v) => (v === null || v === undefined ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const b = (v) => (v ? "true" : "false");

let sql = `-- =============================================================================
-- A MAE Zing Deals | DEMO catalog (optional)
-- Generated by scripts/generate-seed.mjs from supabase/seed-data/catalog.json.
-- Every product is marked availability = 'demo': sample listings, NOT confirmed stock.
-- No "compare at" prices are included because none have been verified.
-- Safe to run more than once (existing slugs or SKUs are skipped).
-- =============================================================================

`;
sql += "insert into public.categories (name, slug, description, color, sort_order) values\n";
sql += data.categories.map((c) => `  (${q(c.name)}, ${q(c.slug)}, ${q(c.description)}, ${q(c.color)}, ${c.sort_order})`).join(",\n");
sql += "\non conflict (slug) do nothing;\n\n";

sql += "insert into public.products (category_id, name, slug, description, price_cents, sku, inventory_qty, availability, is_featured, is_bestseller, is_new, is_published)\nselect c.id, v.name, v.slug, v.description, v.price_cents, v.sku, v.inventory_qty, 'demo', v.is_featured, v.is_bestseller, v.is_new, true\nfrom (values\n";
sql += data.products
  .map((p) => `  (${q(p.category)}, ${q(p.name)}, ${q(p.slug)}, ${q(p.description)}, ${p.price_cents}, ${q(p.sku)}, ${p.inventory_qty}, ${b(p.is_featured)}, ${b(p.is_bestseller)}, ${b(p.is_new)})`)
  .join(",\n");
sql += "\n) as v(category, name, slug, description, price_cents, sku, inventory_qty, is_featured, is_bestseller, is_new)\njoin public.categories c on c.slug = v.category\non conflict do nothing;\n";

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), sql);
console.log(`seed.sql: ${data.categories.length} categories, ${data.products.length} products`);
